#!/usr/bin/env python3
# Slate board v0.1.0 — generated by the Slate plugin; do not edit, run /slate:upgrade
SLATE_VERSION = "0.1.0"
SCHEMA_VERSION = 1

# The only thing that changes kanban/tickets.json. Python 3.9+ standard library only.
#
# Run from the repo root (python3 kanban/board.py next) or from kanban/ (python3 board.py next).
# tickets.json always lives next to this file. Every write validates the whole board first
# and writes atomically (temp file in the same folder, then rename) with stable formatting.
#
# Exit codes: 0 ok, 1 validation error or refused action, 2 usage error.
# Run `python3 kanban/board.py --help` or `python3 kanban/board.py <command> --help`.

